import{_ as t,o as a,c as r,a5 as i}from"./chunks/framework.kcd3e0J6.js";const n="/study/images/graphics/pipeline-compilation-stutter.svg",m=JSON.parse('{"title":"シェーダーコンパイルのカクつきとパイプラインキャッシュ","description":"","frontmatter":{"title":"シェーダーコンパイルのカクつきとパイプラインキャッシュ","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"描画時にパイプラインを初めて作ると処理が止まる理由と、事前作成やキャッシュで減らせる作業を調べる。","aliases":["shader compilation stutter","シェーダーコンパイルスタッター","PSO","Pipeline State Object","パイプラインキャッシュ","PSOキャッシュ","事前作成","プリウォーム","VkPipelineCache","ID3D12PipelineLibrary"],"verification":"Vulkanのパイプライン作成・キャッシュ仕様と、Direct3D 12のPSO・Pipeline Library・PIX Timing Captureの公式資料に照合（2026-11-06）"}},"headers":[],"relativePath":"graphics/optimization/pipeline-compilation-stutter.md","filePath":"graphics/optimization/pipeline-compilation-stutter.md"}'),s={name:"graphics/optimization/pipeline-compilation-stutter.md"};function o(l,e,p,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="シェーダーコンパイルのカクつきとパイプラインキャッシュ" tabindex="-1">シェーダーコンパイルのカクつきとパイプラインキャッシュ <a class="header-anchor" href="#シェーダーコンパイルのカクつきとパイプラインキャッシュ" aria-label="Permalink to &quot;シェーダーコンパイルのカクつきとパイプラインキャッシュ&quot;">​</a></h1><p>初めて炎のエフェクトが出た瞬間だけゲームが止まり、次から滑らかに表示されることがあります。原因候補の一つは、描画に必要なパイプラインをその場で作り、レンダースレッドが作成の完了を待つことです。APIを呼び出してから戻るまでには、GPU向けのコード生成や状態の検証、ドライバ内部の待ちなどが入り得ます。原因を調べるには、まずパイプライン作成が起きた時刻を記録します。<a href="https://docs.vulkan.org/refpages/latest/refpages/source/VK_EXT_pipeline_creation_cache_control.html" target="_blank" rel="noreferrer">Khronosのパイプライン作成コストの解説</a></p><h2 id="シェーダーをビルドしたあとに残る処理" tabindex="-1">シェーダーをビルドしたあとに残る処理 <a class="header-anchor" href="#シェーダーをビルドしたあとに残る処理" aria-label="Permalink to &quot;シェーダーをビルドしたあとに残る処理&quot;">​</a></h2><p>ゲームのビルドでシェーダーを <a href="/study/graphics/shader/spirv.html">SPIR-VやDXILの中間表現</a> に変換しておけば、シェーダーのソースから中間表現を作る仕事を実行時から外せます。実行先のGPUで描画を行うには、どのシェーダーを組み合わせ、どの形式の画像に、どんな深度・ブレンド設定で書くかをAPIに渡して、パイプラインを作ります。ドライバは、この組み合わせに合わせたGPU向けの処理を、必要に応じて行います。<a href="https://docs.vulkan.org/refpages/latest/refpages/source/vkCreateGraphicsPipelines.html" target="_blank" rel="noreferrer">Vulkanのグラフィックスパイプライン作成</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/managing-graphics-pipeline-state-in-direct3d-12" target="_blank" rel="noreferrer">Direct3D 12のパイプライン状態</a></p><p>Direct3D 12でこの組み合わせをまとめたものが <strong>PSO（Pipeline State Object）</strong> です。例えば同じ頂点・ピクセルシェーダーでも、描画先の形式やサンプル数が違えば、別のPSOが必要です。一方、ビューポートのように描画コマンドで指定できる状態は、PSOの作成に必要な状態と分けます。Vulkanでも、パイプライン作成時に固定する状態と、コマンドで指定する動的状態があります。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/managing-graphics-pipeline-state-in-direct3d-12#graphics-pipeline-states-set-with-pipeline-state-objects" target="_blank" rel="noreferrer">Direct3D 12のPSOに入る状態と別に設定する状態</a> · <a href="https://docs.vulkan.org/guide/latest/dynamic_state.html" target="_blank" rel="noreferrer">Vulkanの動的状態</a></p><h2 id="初めて使うフレームで何を待つか" tabindex="-1">初めて使うフレームで何を待つか <a class="header-anchor" href="#初めて使うフレームで何を待つか" aria-label="Permalink to &quot;初めて使うフレームで何を待つか&quot;">​</a></h2><p>次の図では、同じ描画に向かうレンダースレッドの時間だけを比べます。どちらもフレーム開始から描画の準備に4 msかかり、作成済みのパイプラインの取得と描画の投入に1 msかかるとします。初回使用時にパイプラインを作ると、その間に24 msのAPI呼び出しが挟まります。</p><figure class="study-figure"><img src="'+n+'" alt="初回使用時に作ると、CPUの描画準備4 ms、パイプライン作成24 ms、取得と投入1 msで29 msかかる。ロード中に作成済みなら、同じフレームでは準備と取得・投入だけの5 msで済む。破線は60 FPSのフレーム間隔約16.67 ms。" width="760" height="325" loading="lazy"><figcaption>説明用の時間です。60 FPSの目安と、CPUが描画を投入するまでの時間を比べています。<a href="/study/images/graphics/pipeline-compilation-stutter.svg" target="_blank" rel="noopener noreferrer">初回作成と事前作成の図を拡大</a></figcaption></figure><table tabindex="0"><thead><tr><th>作成のタイミング</th><th style="text-align:right;">フレーム開始から描画を投入するまで</th><th>作成にかかった24 ms</th></tr></thead><tbody><tr><td>初回の描画時</td><td style="text-align:right;">29 ms</td><td>描画を投入する前に待つ</td></tr><tr><td>ロード中に作成済み</td><td style="text-align:right;">5 ms</td><td>ロード中に支払う</td></tr></tbody></table><p>既にGPUに描画が積まれている場合、作成待ちの間もGPUは仕事を続けられます。描画が間に合わなくなると、GPUのキューが空く区間や表示間隔の長い区間が見えることがあります。前後関係を確認するため、CPU上の作成呼び出し、GPU上の描画、画面の切り替わりをそれぞれ計測します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3dtools/pix/articles/timing-captures/pix-timing-captures#gpu-timings" target="_blank" rel="noreferrer">PIX Timing CaptureのGPUタイミング</a> · <a href="/study/graphics/optimization/frame-pacing.html">フレームタイムとフレームペーシング</a></p><h2 id="キャッシュのどの層で再利用するか" tabindex="-1">キャッシュのどの層で再利用するか <a class="header-anchor" href="#キャッシュのどの層で再利用するか" aria-label="Permalink to &quot;キャッシュのどの層で再利用するか&quot;">​</a></h2><table tabindex="0"><thead><tr><th>層</th><th>保存するもの</th><th>次に使うとき</th></tr></thead><tbody><tr><td>アプリ内のオブジェクト表</td><td>作成済みの <code>VkPipeline</code> や <code>ID3D12PipelineState</code></td><td>同じデバイスで、表から取り出して使う</td></tr><tr><td>作成時に使うキャッシュ</td><td><code>VkPipelineCache</code> にドライバが記録するデータや、<code>ID3D12PipelineLibrary</code> に登録したPSO</td><td>同じ構成のパイプラインを作成・取得するときに利用する</td></tr><tr><td>永続化したバイト列</td><td>キャッシュやライブラリを保存用に取り出したデータ</td><td>次回起動時に対応するAPIに渡し、作成・取得の処理で使う</td></tr></tbody></table><p>アプリの表のキーには、シェーダーの中身とエントリーポイント、固定する描画状態、出力形式、レイアウトやルートシグネチャなど、作るパイプラインを区別する情報を入れます。Vulkanの特殊化定数を使う場合はその値も含めます。キーの比較には状態の内容を使います。例えば一時メモリ上のシェーダーのポインタを使うと、同じ内容を別の場所に読み込んだときに一致しません。<a href="https://docs.vulkan.org/refpages/latest/refpages/source/VkPipelineShaderStageCreateInfo.html" target="_blank" rel="noreferrer">Vulkanのシェーダーステージと特殊化情報</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/ns-d3d12-d3d12_graphics_pipeline_state_desc" target="_blank" rel="noreferrer">Direct3D 12のPSO記述</a></p><p>Vulkanで <code>vkGetPipelineCacheData</code> が返すデータは、あとで <code>vkCreatePipelineCache</code> に渡せます。ヘッダーにはベンダーID、デバイスID、キャッシュのUUIDなどがあり、互換性がないデータを渡すとキャッシュは空で始まります。Direct3D 12では、対応環境で <code>ID3D12PipelineLibrary</code> を使い、<code>Serialize</code> したデータを次回の <code>CreatePipelineLibrary</code> に渡せます。ドライバやアダプターが合わず拒否された場合に備え、空のキャッシュから作れる経路を残します。保存したバイト列がある場合も、アプリが直接バインドできるオブジェクトを得るには作成・取得の処理が必要です。<a href="https://docs.vulkan.org/refpages/latest/refpages/source/VkPipelineCacheCreateInfo.html" target="_blank" rel="noreferrer">Vulkanのキャッシュ初期データ</a> · <a href="https://docs.vulkan.org/refpages/latest/refpages/source/VkPipelineCacheHeaderVersionOne.html" target="_blank" rel="noreferrer">Vulkanのキャッシュヘッダー</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12device1-createpipelinelibrary" target="_blank" rel="noreferrer">Direct3D 12のライブラリ作成と互換性</a></p><h2 id="初回の停止を見つけ、再計測する" tabindex="-1">初回の停止を見つけ、再計測する <a class="header-anchor" href="#初回の停止を見つけ、再計測する" aria-label="Permalink to &quot;初回の停止を見つけ、再計測する&quot;">​</a></h2><ol><li><strong>作成した時刻と理由を記録する。</strong> <code>CreateGraphicsPipelineState</code> や <code>vkCreateGraphicsPipelines</code> の前後にCPUマーカーを付け、経過時間、描画パス、キー、アプリのオブジェクト表で新規作成になったかを残します。Vulkanでパイプライン作成フィードバックを取るなら、有効ビットを確認します。キャッシュヒットのフラグが指すのは、作成APIに渡した <code>VkPipelineCache</code> で再利用できた場合です。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3dtools/pix/articles/timing-captures/layouts/pix-timing-captures-timeline-layout#core-lanes" target="_blank" rel="noreferrer">PIXのCPUマーカー</a> · <a href="https://docs.vulkan.org/refpages/latest/refpages/source/VkPipelineCreationFeedbackFlagBits.html" target="_blank" rel="noreferrer">Vulkanの作成フィードバックフラグ</a></li><li><strong>同じ場面で比較する。</strong> 保存データを使わずに起動した場合、保存データを読み込んで起動した場合、同じ起動中の2回目を分けます。カクつきと同じ時刻に作成処理や作成を待つ区間があるかを確認し、I/OやGPU上のパスも時系列で比較します。アプリの保存データを外しても、実装が内部で保持するキャッシュが効く場合があります。試験の条件には、どの層のキャッシュを使ったかを記録します。<a href="https://docs.vulkan.org/refpages/latest/refpages/source/vkCreateGraphicsPipelines.html" target="_blank" rel="noreferrer">Vulkanの実装側キャッシュに関する注記</a> · <a href="/study/graphics/optimization/gpu-timestamp-queries.html">GPUタイムスタンプクエリ</a></li><li><strong>使用される組み合わせを先に作る。</strong> 実際に使ったキーの一覧から、場面の開始直後に使うものを優先してロード中やバックグラウンドで作ります。並列ジョブの数を制限し、同じキーを同時に何度も作らず、描画前に完成したオブジェクトを受け取ります。再計測では、初回の停止に加え、ロード時間、作成待ちの回数、作成済みオブジェクトのメモリ使用量も比べます。<a href="https://docs.vulkan.org/samples/latest/samples/performance/pipeline_cache/README.html" target="_blank" rel="noreferrer">Khronosのパイプラインキャッシュ実践例</a></li></ol><p>Vulkanで <code>pipelineCreationCacheControl</code> を有効にしている場合、<code>VK_PIPELINE_CREATE_FAIL_ON_PIPELINE_COMPILE_REQUIRED_BIT</code> を指定すると、コンパイルが必要な作成は <code>VK_PIPELINE_COMPILE_REQUIRED</code> を返します。このとき有効なパイプラインは得られないため、その描画を後に回すか、互換性のある作成済みの代替を選び、別途作成を予約します。このフラグを使う場合も、作成の呼び出しにかかる時間は計測します。<a href="https://docs.vulkan.org/spec/latest/chapters/pipelines.html#VkPipelineCreateFlagBits" target="_blank" rel="noreferrer">Vulkanのパイプライン作成フラグ</a></p><p>関連項目は<a href="/study/graphics/optimization/tools.html">デバッグ・プロファイリングツール</a>と<a href="/study/game/asset-loading.html">アセットロード</a>です。</p>',18)])])}const u=t(s,[["render",o]]);export{m as __pageData,u as default};
